package com.creatorhub.model; public class Challenge {private int challengeId,participantCount; private String title,category,description,deadline,teamSize,prize; private boolean joined; public int getChallengeId(){return challengeId;} public void setChallengeId(int v){challengeId=v;} public int getParticipantCount(){return participantCount;} public void setParticipantCount(int v){participantCount=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getDeadline(){return deadline;} public void setDeadline(String v){deadline=v;} public String getTeamSize(){return teamSize;} public void setTeamSize(String v){teamSize=v;} public String getPrize(){return prize;} public void setPrize(String v){prize=v;} public boolean isJoined(){return joined;} public void setJoined(boolean v){joined=v;}}
